if doc.reference_doctype in ["CRM Deal", "CRM Lead"]:
    try:
        # Fetch the referenced document (CRM Deal or CRM Lead)
        reference_doc = frappe.get_doc(doc.reference_doctype, doc.reference_name)

        # Update the modified time
        reference_doc.modified = frappe.utils.now()

        # Save the changes without triggering events
        reference_doc.db_update()

    except Exception as e:
        frappe.log_error(f"Error updating {doc.reference_doctype} modified time: {str(e)}", "CRM Update Error")
